//
//  LegalUpdate.swift
//  CarryAwareNJ
//
//  Remotely managed legal, community, safety, and app updates.
//

import Foundation

enum UpdateAlertType: String, Codable, CaseIterable, Identifiable {
    case legal
    case community
    case safety
    case appAnnouncement

    var id: String { rawValue }

    var title: String {
        switch self {
        case .legal:
            return "Legal & Legislative"
        case .community:
            return "Community News"
        case .safety:
            return "Safety Notices"
        case .appAnnouncement:
            return "App Announcements"
        }
    }

    var shortTitle: String {
        switch self {
        case .legal:
            return "Legal"
        case .community:
            return "Community"
        case .safety:
            return "Safety"
        case .appAnnouncement:
            return "App"
        }
    }

    var systemImage: String {
        switch self {
        case .legal:
            return "building.columns"
        case .community:
            return "person.3"
        case .safety:
            return "exclamationmark.shield"
        case .appAnnouncement:
            return "app.badge"
        }
    }

    var preferenceKey: String {
        switch self {
        case .legal:
            // Preserve the preference used by existing releases.
            return "legalUpdatesEnabled"
        case .community:
            return "communityUpdatesEnabled"
        case .safety:
            return "safetyNoticesEnabled"
        case .appAnnouncement:
            return "appAnnouncementsEnabled"
        }
    }

    var topicName: String {
        switch self {
        case .legal:
            return "carryaware-legal"
        case .community:
            return "carryaware-community"
        case .safety:
            return "carryaware-safety"
        case .appAnnouncement:
            return "carryaware-app"
        }
    }
}

struct LegalUpdate: Identifiable, Codable, Hashable {
    let id: String
    let type: UpdateAlertType
    let title: String
    let summary: String
    let category: String
    let status: String
    let date: String
    let sourceTitle: String
    let sourceURL: String
    let isImportant: Bool

    private enum CodingKeys: String, CodingKey {
        case id
        case type
        case title
        case summary
        case category
        case status
        case date
        case sourceTitle
        case sourceURL
        case isImportant
    }

    init(
        id: String,
        type: UpdateAlertType,
        title: String,
        summary: String,
        category: String,
        status: String,
        date: String,
        sourceTitle: String,
        sourceURL: String,
        isImportant: Bool
    ) {
        self.id = id
        self.type = type
        self.title = title
        self.summary = summary
        self.category = category
        self.status = status
        self.date = date
        self.sourceTitle = sourceTitle
        self.sourceURL = sourceURL
        self.isImportant = isImportant
    }

    init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)

        id = try container.decode(String.self, forKey: .id)
        // Feeds produced before typed alerts are legal updates.
        type = try container.decodeIfPresent(UpdateAlertType.self, forKey: .type) ?? .legal
        title = try container.decode(String.self, forKey: .title)
        summary = try container.decode(String.self, forKey: .summary)
        category = try container.decodeIfPresent(String.self, forKey: .category) ?? ""
        status = try container.decodeIfPresent(String.self, forKey: .status) ?? ""
        date = try container.decodeIfPresent(String.self, forKey: .date) ?? ""
        sourceTitle = try container.decodeIfPresent(String.self, forKey: .sourceTitle) ?? ""
        sourceURL = try container.decodeIfPresent(String.self, forKey: .sourceURL) ?? ""
        isImportant = try container.decodeIfPresent(Bool.self, forKey: .isImportant) ?? false
    }

    init?(notificationUserInfo: [AnyHashable: Any]) {
        func stringValue(_ key: String) -> String? {
            if let value = notificationUserInfo[key] as? String, !value.isEmpty {
                return value
            }
            return nil
        }

        guard
            let id = stringValue("updateID"),
            let title = stringValue("updateTitle")
        else {
            return nil
        }

        let type = stringValue("updateType")
            .flatMap(UpdateAlertType.init(rawValue:)) ?? .legal

        let aps = notificationUserInfo["aps"] as? [String: Any]
        let alert = aps?["alert"] as? [String: Any]
        let notificationBody = alert?["body"] as? String

        self.init(
            id: id,
            type: type,
            title: title,
            summary: stringValue("updateSummary") ?? notificationBody ?? "",
            category: stringValue("updateCategory") ?? type.title,
            status: stringValue("updateStatus") ?? "",
            date: stringValue("updateDate") ?? "",
            sourceTitle: stringValue("sourceTitle") ?? "",
            sourceURL: stringValue("sourceURL") ?? "",
            isImportant: stringValue("isImportant")?.lowercased() != "false"
        )
    }

    var source: URL? {
        guard !sourceURL.isEmpty else { return nil }
        return URL(string: sourceURL)
    }

    var metadataLine: String {
        [category, status]
            .filter { !$0.isEmpty }
            .joined(separator: " • ")
    }

    var popupDisclaimer: String {
        switch type {
        case .legal:
            return "Informational summary only. Always verify current law and official guidance."
        case .community, .safety, .appAnnouncement:
            return "Informational summary only. Review the linked source for full details."
        }
    }
}

enum UpdateAlertPreferences {
    static func registerDefaults(in defaults: UserDefaults = .standard) {
        defaults.register(defaults: Dictionary(
            uniqueKeysWithValues: UpdateAlertType.allCases.map { ($0.preferenceKey, true) }
        ))
    }

    static func isEnabled(
        _ type: UpdateAlertType,
        in defaults: UserDefaults = .standard
    ) -> Bool {
        defaults.object(forKey: type.preferenceKey) == nil
            ? true
            : defaults.bool(forKey: type.preferenceKey)
    }
}

//
//  LegalUpdatesView.swift
//  CarryAwareNJ
//
//  Filterable archive for remotely managed alerts and updates.
//

import SwiftUI

private enum UpdateArchiveFilter: String, CaseIterable, Identifiable {
    case all
    case legal
    case community
    case safety
    case appAnnouncement

    var id: String { rawValue }

    var title: String {
        switch self {
        case .all:
            return "All"
        case .legal:
            return UpdateAlertType.legal.shortTitle
        case .community:
            return UpdateAlertType.community.shortTitle
        case .safety:
            return UpdateAlertType.safety.shortTitle
        case .appAnnouncement:
            return UpdateAlertType.appAnnouncement.shortTitle
        }
    }

    var updateType: UpdateAlertType? {
        switch self {
        case .all:
            return nil
        case .legal:
            return .legal
        case .community:
            return .community
        case .safety:
            return .safety
        case .appAnnouncement:
            return .appAnnouncement
        }
    }
}

struct LegalUpdatesView: View {
    @State private var updates: [LegalUpdate] = LegalUpdateManager.cachedUpdates()
    @State private var selectedFilter: UpdateArchiveFilter = .all
    @State private var isLoading = false

    private var filteredUpdates: [LegalUpdate] {
        guard let type = selectedFilter.updateType else { return updates }
        return updates.filter { $0.type == type }
    }

    var body: some View {
        List {
            Section {
                Text("CarryAwareNJ provides informational summaries with links to the original source. Always verify current law, official guidance, and posted signage when applicable.")
                    .font(.footnote)
                    .foregroundStyle(.secondary)
            }

            Section {
                Picker("Show", selection: $selectedFilter) {
                    ForEach(UpdateArchiveFilter.allCases) { filter in
                        Text(filter.title).tag(filter)
                    }
                }
                .pickerStyle(.menu)
            } header: {
                Text("Filter")
            }

            if filteredUpdates.isEmpty {
                Section {
                    VStack(alignment: .leading, spacing: 8) {
                        Text(emptyStateTitle)
                            .font(.headline)

                        Text(emptyStateMessage)
                            .font(.subheadline)
                            .foregroundStyle(.secondary)
                    }
                    .padding(.vertical, 4)
                }
            } else {
                Section("Update History") {
                    ForEach(filteredUpdates) { update in
                        updateRow(update)
                    }
                }
            }
        }
        .navigationTitle("Alerts & Updates")
        .navigationBarTitleDisplayMode(.inline)
        .onAppear {
            refresh()
        }
    }

    private var emptyStateTitle: String {
        if isLoading {
            return "Checking for updates…"
        }

        return selectedFilter == .all
            ? "No updates are available yet."
            : "No \(selectedFilter.title.lowercased()) updates yet."
    }

    private var emptyStateMessage: String {
        if selectedFilter == .all {
            return "Legal, community, safety, and CarryAwareNJ app announcements will remain available here after publication."
        }

        return "Choose another filter to review other published alerts and updates."
    }

    @ViewBuilder
    private func updateRow(_ update: LegalUpdate) -> some View {
        VStack(alignment: .leading, spacing: 9) {
            HStack(alignment: .firstTextBaseline, spacing: 8) {
                Label(update.type.shortTitle, systemImage: update.type.systemImage)
                    .font(.caption.weight(.semibold))
                    .foregroundStyle(update.type.tintColor)

                Spacer()

                if update.isImportant {
                    Image(systemName: "exclamationmark.circle.fill")
                        .foregroundStyle(.orange)
                        .accessibilityLabel("Important update")
                }
            }

            Text(update.title)
                .font(.headline)

            let details = [update.date, update.category, update.status]
                .filter { !$0.isEmpty }
                .joined(separator: " • ")

            if !details.isEmpty {
                Text(details)
                    .font(.caption)
                    .foregroundStyle(.secondary)
            }

            Text(update.summary)
                .font(.subheadline)

            if let source = update.source {
                Link(destination: source) {
                    Label("View Source", systemImage: "arrow.up.right.square")
                        .font(.subheadline)
                }

                if !update.sourceTitle.isEmpty {
                    Text(update.sourceTitle)
                        .font(.caption)
                        .foregroundStyle(.secondary)
                }
            }
        }
        .padding(.vertical, 6)
    }

    private func refresh() {
        isLoading = true

        LegalUpdateManager.loadUpdates { loadedUpdates in
            DispatchQueue.main.async {
                updates = loadedUpdates
                isLoading = false
            }
        }
    }
}

private extension UpdateAlertType {
    var tintColor: Color {
        switch self {
        case .legal:
            return .orange
        case .community:
            return .blue
        case .safety:
            return .red
        case .appAnnouncement:
            return .purple
        }
    }
}

//
//  RootView.swift
//  CarryAwareNJ
//
//  Created by Matthew Mignone on 3/28/26.
//

import Combine
import SwiftUI

struct RootView: View {
    @EnvironmentObject private var appState: AppState
    @Environment(\.openURL) private var openURL
    @Environment(\.scenePhase) private var scenePhase
    @AppStorage("dailyLibertyWidgetPromptShown")
    private var dailyLibertyWidgetPromptShown: Bool = false

    @State private var activeUpdate: LegalUpdate?
    @State private var isCheckingUpdates = false
    @State private var isMainInterfaceReady = false
    @State private var showArchiveReminder = false
    @State private var showDailyLibertyWidgetPrompt = false

    private let updateRefreshTimer = Timer.publish(
        every: 90,
        on: .main,
        in: .common
    ).autoconnect()

    var body: some View {
        Group {
            if appState.needsDisclaimerAcceptance {
                DisclaimerView()
            } else if appState.isPreparingSafetyData {
                LaunchLoadingView(statusText: appState.debugStatus)
            } else {
                MainTabView()
                    .onAppear {
                        isMainInterfaceReady = true
                        resumePendingNotificationWork()
                        scheduleDailyLibertyWidgetPromptIfNeeded()
                    }
                    .onDisappear {
                        isMainInterfaceReady = false
                    }
            }
        }
        .onChange(of: scenePhase) { _, newPhase in
            guard newPhase == .active, isMainInterfaceReady else { return }
            resumePendingNotificationWork()
            scheduleDailyLibertyWidgetPromptIfNeeded()
        }
        .onReceive(updateRefreshTimer) { _ in
            resumePendingNotificationWork()
        }
        .onReceive(
            NotificationCenter.default.publisher(for: .carryAwareNotificationResponseReady)
        ) { _ in
            // Sent on a later main-queue turn, after the system completion has
            // returned. Handles responses arriving before OR after activation.
            resumePendingNotificationWork()
        }
        .onReceive(
            NotificationCenter.default.publisher(for: .carryAwareRemoteUpdateReceived)
        ) { _ in
            presentPendingPushUpdateIfNeeded()
        }
        .onChange(of: activeUpdate?.id) { _, newID in
            if newID == nil { resumePendingNotificationWorkOnNextTurn() }
        }
        .onChange(of: showArchiveReminder) { _, showing in
            if !showing { resumePendingNotificationWorkOnNextTurn() }
        }
        .onChange(of: showDailyLibertyWidgetPrompt) { _, showing in
            if !showing { resumePendingNotificationWorkOnNextTurn() }
        }
        .alert(item: $activeUpdate) { update in
            Alert(
                title: Text(update.title),
                message: Text(popupMessage(for: update)),
                primaryButton: .default(Text("View Source")) {
                    LegalUpdateManager.markSeen(update)

                    if let source = update.source {
                        openURL(source)
                    }
                },
                secondaryButton: .cancel(Text("Dismiss")) {
                    LegalUpdateManager.markSeen(update)

                    if LegalUpdateManager.recordDismissalAndShouldShowArchiveReminder() {
                        DispatchQueue.main.asyncAfter(deadline: .now() + 0.4) {
                            guard canPresentNotificationUI else { return }
                            showArchiveReminder = true
                        }
                    }
                }
            )
        }
        .alert("Past Alerts & Updates", isPresented: $showArchiveReminder) {
            Button("Got It", role: .cancel) {}
        } message: {
            Text("Past alerts and updates are always available under Resources → CarryAwareNJ Alerts & Updates.")
        }
        .sheet(isPresented: $showDailyLibertyWidgetPrompt) {
            DailyLibertyWidgetPromptView()
        }
    }

    private var canPresentNotificationUI: Bool {
        scenePhase == .active && isMainInterfaceReady
            && activeUpdate == nil && !showArchiveReminder && !showDailyLibertyWidgetPrompt
    }

    private func resumePendingNotificationWorkOnNextTurn() {
        DispatchQueue.main.async {
            resumePendingNotificationWork()
        }
    }

    private func resumePendingNotificationWork() {
        guard canPresentNotificationUI else { return }
        if handlePendingNotificationActionIfNeeded() { return }
        presentPendingPushUpdateIfNeeded()
        checkForUpdate()
    }

    private func popupMessage(for update: LegalUpdate) -> String {
        let metadata = [update.category, update.status]
            .filter {
                !$0.isEmpty
                    && $0.caseInsensitiveCompare(update.type.title) != .orderedSame
            }
            .joined(separator: " • ")

        let heading = [update.type.title, metadata]
            .filter { !$0.isEmpty }
            .joined(separator: "\n")

        return "\(heading)\n\n\(update.summary)\n\n\(update.popupDisclaimer)"
    }

    private func checkForUpdate() {
        guard canPresentNotificationUI, !isCheckingUpdates else { return }
        guard UpdateAlertType.allCases.contains(where: {
            UpdateAlertPreferences.isEnabled($0)
        }) else {
            return
        }

        isCheckingUpdates = true

        LegalUpdateManager.loadUpdates { updates in
            DispatchQueue.main.async {
                isCheckingUpdates = false

                // The network request may finish after the app backgrounds.
                guard canPresentNotificationUI else { return }
                guard let update = LegalUpdateManager.newestUnseenImportantUpdate(
                    in: updates
                ) else {
                    return
                }

                activeUpdate = update
            }
        }
    }

    @discardableResult
    private func handlePendingNotificationActionIfNeeded() -> Bool {
        guard canPresentNotificationUI else { return false }
        guard NotificationDelegate.shared.consumePendingStatuteAction() else {
            return false
        }

        openURL(RestrictedPlaceType.njStatuteURL)
        return true
    }

    private func presentPendingPushUpdateIfNeeded() {
        // Do not remove a pending update while loading, inactive, or covered by
        // another popup. A later activation/response/dismissal will retry it.
        guard canPresentNotificationUI else { return }
        guard let update = NotificationDelegate.shared.consumePendingUpdate() else {
            return
        }

        presentIfEligible(update)
    }

    private func presentIfEligible(_ update: LegalUpdate) {
        guard canPresentNotificationUI else { return }
        guard LegalUpdateManager.shouldPresent(update) else { return }

        activeUpdate = update
    }

    private func scheduleDailyLibertyWidgetPromptIfNeeded() {
        guard scenePhase == .active, isMainInterfaceReady else { return }
        guard !dailyLibertyWidgetPromptShown else { return }
        guard !showDailyLibertyWidgetPrompt else { return }

        DispatchQueue.main.asyncAfter(deadline: .now() + 2.0) {
            guard scenePhase == .active, isMainInterfaceReady else { return }
            guard !dailyLibertyWidgetPromptShown else { return }

            if activeUpdate != nil || showArchiveReminder {
                scheduleDailyLibertyWidgetPromptIfNeeded()
                return
            }

            dailyLibertyWidgetPromptShown = true
            showDailyLibertyWidgetPrompt = true
        }
    }
}
